vosi:tableset:
{%- for schema in schemas %}

    {{ schema.schema_name }}
    {%- if schema.description %}
    {{ schema.description }}
    {%- endif %}
    {%- for table in schema.tables %}

      {{ table.table_name }}
      {%- if table.description %}
      {{ table.description }}
      {%- endif %}
      {%- for column in table.columns %}

        {{ column.column_name }}
        {%- for element in ["description", "unit", "ucd", "utype"] %}
        {%- if column[element] %}
        <{{ element }}>{{ column[element] }}</{{ element }}>
        {%- endif %}
        {%- endfor %}
        {{ column.datatype }}
        {%- if column.indexed %}
        indexed
        {%- endif %}
        {%- if column.principal %}
        principal
        {%- endif %}

      {%- endfor %}

    {%- endfor %}

{%- endfor %}
